sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

var hospitalSysId = gs.getProperty('x_1520874_teleco_0.city_hospital_Comp_ID');

if (hospitalSysId) {
    current.company = hospitalSysId;
} else {
    gs.warn('Inbound Email Error: System Property x_1520874_teleco_0.city_hospital_Comp_ID.');
}

current.contact_type = 'email';
current.short_description = email.subject;
current.priority = 1; // Critical Incident 

var rawBody = email.body_text || email.body_html || "No content provided in the email.";
// Regex to strip any HTML tags (e.g., <p>, <br>) so our parser can read clean text
var cleanBody = rawBody.replace(/<[^>]*>?/gm, '');

current.description = "URGENT NETWORK ALERT FROM CITY HOSPITAL\n";
current.description += "--------------------------------------\n";
current.description += "Raw Alert Details:\n" + cleanBody.trim();

current.insert();
})(current, event, email, logger, classifier);
